    parents = {}
    def build(node, parent):
        parents[node] = parent
        for c in node.children:
            build(c, node)
    build(self, None)
    def rebuild(node, parent):
        children = [rebuild(c, node) for c in node.children if c is not parent]
        return Tree(node.label, children)
    # find the node object
    def find(node, target):
        if node.label == target:
            return node
        for c in node.children:
            r = find(c, target)
            if r is not None:
                return r
        return None
    target = find(self, from_node)
    return rebuild(target, parents[target])
```

